 patho:"When compensation fails, rising ICP lowers cerebral perfusion. Late, the brainstem is compressed, producing Cushing's triad: rising systolic BP with widening pulse pressure, bradycardia, and irregular respirations.",
 risk:["Head injury, stroke, brain tumor, meningitis, hydrocephalus"],
 findings:["Early: change in LOC (restlessness, confusion, drowsiness) — the most sensitive sign","Headache, vomiting (may be without nausea)","Pupil changes: sluggish, unequal, dilated","Infants: bulging fontanel, high-pitched cry, increasing head circumference"],
 red:["Cushing's triad (late)","Fixed, dilated pupil","Decerebrate or decorticate posturing"],
 assess:["Glasgow Coma Scale and pupils on schedule","Vital signs for triad","Clear drainage from nose or ears after head injury (possible CSF; test per policy)"],
 prio:["LOC change is the earliest sign: report it promptly","Reduce activities that raise ICP"],
 interv:{nurse:["HOB 30°, head midline, avoid neck and hip flexion","Quiet room, dim lights, cluster care","Avoid straining, coughing, and suctioning beyond need","Prevent fever"],orders:["Osmotic diuretic (mannitol), oxygenation, seizure prevention per order"],escalate:["Report decreasing LOC, pupil change, or vital-sign triad immediately"]},
 meds:[["Mannitol","Pulls fluid from brain; watch I&O, electrolytes"],["Stool softener","Prevents straining"],["Antiseizure drugs","As ordered"]],
 teach:["Family: keep stimulation low; why care is clustered","After discharge for mild head injury: report worsening headache, vomiting, confusion"],
